#pragma once
#include <torch/extension.h>
#include <cuda_runtime.h>

void gemm_cutlass(
    torch::Tensor& C,
    const torch::Tensor& A,
    const torch::Tensor& B,
    cudaStream_t stream);

#include "kernel.h"

#include <cutlass/cutlass.h>
#include <cutlass/gemm/device/gemm_universal.h>
#include <cutlass/epilogue/thread/linear_combination.h>
#include <cutlass/gemm/threadblock/threadblock_swizzle.h>
#include <cutlass/gemm/threadblock/threadblock_swizzle_streamk.h>
#include <cutlass/half.h>

using ElementA = cutlass::half_t;
using LayoutA = cutlass::layout::RowMajor;
using ElementB = cutlass::half_t;
using LayoutB = cutlass::layout::ColumnMajor;
using ElementC = cutlass::half_t;
using LayoutC = cutlass::layout::RowMajor;
using ElementAccumulator = float;

using OperatorClass = cutlass::arch::OpClassTensorOp;
using ArchTag = cutlass::arch::Sm80;
using InstructionShape = cutlass::gemm::GemmShape<16, 8, 16>;

constexpr int AlignmentA = 8;
constexpr int AlignmentB = 8;

using EpilogueOp = cutlass::epilogue::thread::LinearCombination<
    ElementC,
    128 / cutlass::sizeof_bits<ElementC>::value,
    ElementAccumulator,
    ElementAccumulator>;

using Gemm_Large = cutlass::gemm::device::GemmUniversal<
    ElementA, LayoutA,
    ElementB, LayoutB,
    ElementC, LayoutC,
    ElementAccumulator,
    OperatorClass,
    ArchTag,
    cutlass::gemm::GemmShape<256, 128, 32>,
    cutlass::gemm::GemmShape<64, 64, 32>,
    InstructionShape,
    EpilogueOp,
    cutlass::gemm::threadblock::GemmIdentityThreadblockSwizzle<8>,
    3,
    AlignmentA,
    AlignmentB>;

using Gemm_Med = cutlass::gemm::device::GemmUniversal<
    ElementA, LayoutA,
    ElementB, LayoutB,
    ElementC, LayoutC,
    ElementAccumulator,
    OperatorClass,
    ArchTag,
    cutlass::gemm::GemmShape<256, 128, 32>,
    cutlass::gemm::GemmShape<64, 64, 32>,
    InstructionShape,
    EpilogueOp,
    cutlass::gemm::threadblock::ThreadblockSwizzleStreamK,
    3,
    AlignmentA,
    AlignmentB>;

using Gemm_Small = cutlass::gemm::device::GemmUniversal<
    ElementA, LayoutA,
    ElementB, LayoutB,
    ElementC, LayoutC,
    ElementAccumulator,
    OperatorClass,
    ArchTag,
    cutlass::gemm::GemmShape<128, 128, 32>,
    cutlass::gemm::GemmShape<64, 64, 32>,
    InstructionShape,
    EpilogueOp,
    cutlass::gemm::threadblock::ThreadblockSwizzleStreamK,
    4,
    AlignmentA,
    AlignmentB>;

static void* g_workspace = nullptr;
static size_t g_workspace_size = 0;

static void ensure_workspace(size_t needed) {
    if (needed <= g_workspace_size) return;
    if (g_workspace) cudaFree(g_workspace);
    cudaMalloc(&g_workspace, needed);
    g_workspace_size = needed;
}

template <typename GemmOp>
static void run_gemm(
    int M, int N, int K,
    const cutlass::half_t* A_ptr,
    const cutlass::half_t* B_ptr,
    cutlass::half_t* C_ptr,
    cudaStream_t stream) {

    GemmOp gemm_op;

    typename GemmOp::Arguments args(
        cutlass::gemm::GemmUniversalMode::kGemm,
        {M, N, K},
        1,
        {1.0f, 0.0f},
        A_ptr,
        B_ptr,
        C_ptr,
        C_ptr,
        (int64_t)M * K,
        (int64_t)N * K,
        (int64_t)M * N,
        (int64_t)M * N,
        (int64_t)K,
        (int64_t)K,
        (int64_t)N,
        (int64_t)N);

    size_t ws = GemmOp::get_workspace_size(args);
    if (ws > 0) ensure_workspace(ws);

    gemm_op.initialize(args, g_workspace, stream);
    gemm_op.run(stream);
}

void gemm_cutlass(
    torch::Tensor& C,
    const torch::Tensor& A,
    const torch::Tensor& B,
    cudaStream_t stream) {

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    auto A_ptr = reinterpret_cast<const cutlass::half_t*>(A.data_ptr<at::Half>());
    auto B_ptr = reinterpret_cast<const cutlass::half_t*>(B.data_ptr<at::Half>());
    auto C_ptr = reinterpret_cast<cutlass::half_t*>(C.data_ptr<at::Half>());

    if (M >= 512) {
        run_gemm<Gemm_Large>(M, N, K, A_ptr, B_ptr, C_ptr, stream);
    } else if (M >= 128) {
        run_gemm<Gemm_Med>(M, N, K, A_ptr, B_ptr, C_ptr, stream);
    } else {
        run_gemm<Gemm_Small>(M, N, K, A_ptr, B_ptr, C_ptr, stream);
    }
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"

torch::Tensor run(const torch::Tensor& A, const torch::Tensor& B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "inputs must be 2D");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat16, "A must be float16");
    TORCH_CHECK(B.scalar_type() == torch::kFloat16, "B must be float16");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "inputs must be contiguous");

    int M = A.size(0);
    int N = B.size(0);

    auto C = torch::empty({M, N}, A.options());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    gemm_cutlass(C, A, B, stream);
    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("run", &run, "CUTLASS GEMM C = A @ B.T");
}
